{"__advancedHuntingSettings":true,"query":"let Devices = DeviceInfo
| where isnotempty(DeviceId)
| summarize arg_max(Timestamp, *) by DeviceId;
Devices
| extend ObservedState=iff(isempty(OnboardingStatus), "Unknown / empty", OnboardingStatus)
| summarize Devices=count() by ObservedState","selectedWorkspaceIds":["{HuntingWorkspaceId}"]}

{"__advancedHuntingSettings":true,"query":"let Required=datatable(TableName:string)["DeviceInfo", "DeviceProcessEvents", "DeviceRegistryEvents"];
let Observed=
union isfuzzy=true
    (datatable(TableName:string,Timestamp:datetime)[]),
    (DeviceInfo | project TableName="DeviceInfo",Timestamp),
    (DeviceProcessEvents | project TableName="DeviceProcessEvents",Timestamp),
    (DeviceRegistryEvents | project TableName="DeviceRegistryEvents",Timestamp)
| summarize Events=count(),LatestEvent=max(Timestamp) by TableName;
Required | join kind=leftouter Observed on TableName
| extend Events=coalesce(Events,long(0))
| extend EvidenceState=iff(Events == 0,
    "NO EVIDENCE - check hunting data, permissions, lookback and warnings", "Events present")
| project TableName,Events,LatestEvent,EvidenceState","selectedWorkspaceIds":["{HuntingWorkspaceId}"]}
